import numpy as np
import pandas as pd


def generate(observed, spec, seed):
    if observed is not None:
        raise ValueError('Expected observed=None; this is an aggregate-evidence model.')
    model = spec['model']
    ev = model['evidence']
    groups = spec['groups']
    labels = model['band_labels']
    rep = int(model['replication_factor'])
    if len(groups) != 3:
        raise ValueError('Expected three Hb bands.')
    xs, ys, reverse_ys, permutations = [], [], [], []
    for k, group in enumerate(groups):
        if group['label'] != labels[k]:
            raise ValueError('Incorrect group order or label.')
        x = np.asarray(group['x'], dtype=float)
        y = np.asarray(group['y'], dtype=float)
        n = rep * int(ev['n_by_band'][k])
        if x.ndim != 1 or y.ndim != 1 or len(x) != n or len(y) != n:
            raise ValueError('Unexpected marginal dimensions or size.')
        if not (np.all(np.isfinite(x)) and np.all(np.isfinite(y))):
            raise ValueError('Nonfinite concentration.')
        if not (np.all(x > 0) and np.all(y > 0)):
            raise ValueError('Concentrations must be positive.')
        if not (np.all(np.diff(x) > 0) and np.all(np.diff(y) >= 0)):
            raise ValueError('Expected strictly increasing Hb and sorted ferritin.')
        if k == 0:
            valid = np.all(x < ev['severe_cut'])
        elif k == 1:
            valid = np.all((x >= ev['severe_cut']) & (x < ev['anemia_cut']))
        else:
            valid = np.all(x >= ev['anemia_cut'])
        if not valid:
            raise ValueError('Hb band membership failed.')
        if np.count_nonzero(y < ev['iron_cut']) != rep * int(model['depleted_n_by_band'][k]):
            raise ValueError('Incorrect band depletion count.')
        p = np.arange(n, dtype=np.int64)
        if not np.array_equal(np.sort(p), np.arange(n)):
            raise RuntimeError('Invalid local permutation.')
        permutations.append(p)
        xs.append(x)
        ys.append(y[p])
        reverse_ys.append(y[::-1])
    x = np.concatenate(xs)
    y = np.concatenate(ys)
    if len(x) != rep * int(ev['n_total']):
        raise ValueError('Incorrect total count.')
    anemia = x < ev['anemia_cut']
    depleted = y < ev['iron_cut']
    cells = {
        'anemic_low': int(np.count_nonzero(anemia & depleted)),
        'anemic_high': int(np.count_nonzero(anemia & ~depleted)),
        'nonanemic_low': int(np.count_nonzero(~anemia & depleted)),
        'nonanemic_high': int(np.count_nonzero(~anemia & ~depleted))
    }
    for key, value in cells.items():
        if value != rep * int(ev[key]):
            raise RuntimeError('Published joint cells were not preserved.')
    crude_or = (cells['anemic_low'] * cells['nonanemic_high']) / (cells['anemic_high'] * cells['nonanemic_low'])
    rx = pd.Series(x).rank(method='average').to_numpy()
    def spearman(values):
        ry = pd.Series(values).rank(method='average').to_numpy()
        return float(np.corrcoef(rx, ry)[0, 1])
    rho_output = spearman(y)
    rho_lower = spearman(np.concatenate(reverse_ys))
    if not (np.isfinite(rho_output) and np.isfinite(rho_lower)):
        raise RuntimeError('Undefined rank correlation.')
    if rho_lower > rho_output + 1e-12:
        raise RuntimeError('Rank-correlation bound ordering failed.')
    threshold = float(model['estimands']['material_correlation_change'])
    result = pd.DataFrame({
        'row_id': np.arange(len(x), dtype=np.int64),
        'paired_index': np.concatenate(permutations)
    })
    result.attrs['analysis'] = {
        'n_synthetic': int(len(x)),
        'n_source': int(ev['n_total']),
        'cells_synthetic': cells,
        'crude_anemia_or': float(crude_or),
        'spearman_hb_ferritin': rho_output,
        'fixed_marginal_within_band_spearman_bounds': [rho_lower, rho_output],
        'attainable_correlation_change': float(rho_output - rho_lower),
        'attainable_change_exceeds_0_10': bool(rho_output - rho_lower > threshold),
        'interpretation': 'Output is the upper dependence sensitivity endpoint, not an identified source-population correlation.',
        'checks_run': [
            'group order, dimensions and counts',
            'finite positive concentrations and marginal ordering',
            'Hb band membership and exact depletion counts',
            'local permutation completeness',
            'total rows and all four anemia-by-depletion cells',
            'finite correlations and sensitivity-bound ordering'
        ]
    }
    return result

B09_alternative.generator_py:
import numpy as np
import pandas as pd


def generate(observed, spec, seed):
    if observed is not None:
        raise ValueError('Expected observed=None.')
    model = spec['model']
    ev = model['evidence']
    groups = spec['groups']
    if len(groups) != 3:
        raise ValueError('Expected severe, intermediate, nonanemic groups in that order.')
    factor = int(model['replication_factor'])
    rng = np.random.default_rng(seed)
    xs, ys, reference_ys, reverse_ys, assignments = [], [], [], [], []
    diagnostics = []
    for k, group in enumerate(groups):
        x = np.asarray(group['x'], dtype=float)
        y = np.asarray(group['y'], dtype=float)
        n = factor * int(ev['n_by_band'][k])
        if x.ndim != 1 or y.ndim != 1 or len(x) != n or len(y) != n:
            raise ValueError('Incorrect group dimensions or count.')
        if not (np.all(np.isfinite(x)) and np.all(np.isfinite(y))):
            raise ValueError('Nonfinite marginal value.')
        if np.any(x <= 0) or np.any(y <= 0):
            raise ValueError('All marginal values must be positive.')
        if np.any(np.diff(x) <= 0) or np.any(np.diff(y) < 0):
            raise ValueError('Hb must be strictly increasing and ferritin sorted.')
        if k == 0:
            valid_band = np.all(x < ev['severe_cut'])
        elif k == 1:
            valid_band = np.all((x >= ev['severe_cut']) & (x < ev['anemia_cut']))
        else:
            valid_band = np.all(x >= ev['anemia_cut'])
        if not valid_band:
            raise ValueError('Hb band membership mismatch.')
        n_low = int(np.count_nonzero(y < ev['iron_cut']))
        if n_low != factor * int(model['depleted_counts_by_band'][k]):
            raise ValueError('Ferritin depletion count mismatch.')
        p = np.arange(n, dtype=np.int64)
        if not np.array_equal(np.sort(p), np.arange(n)):
            raise AssertionError('Invalid local permutation.')
        reference_p = rng.permutation(n).astype(np.int64)
        xs.append(x)
        ys.append(y[p])
        reference_ys.append(y[reference_p])
        reverse_ys.append(y[::-1])
        assignments.append(p)
        diagnostics.append({'label': str(group['label']), 'n': n,
                            'depleted': n_low,
                            'hb_gm': float(np.exp(np.mean(np.log(x)))),
                            'fe_gm': float(np.exp(np.mean(np.log(y))))})
    x = np.concatenate(xs)
    y = np.concatenate(ys)
    reference_y = np.concatenate(reference_ys)
    anemia = x < ev['anemia_cut']

    def cells_for(values):
        low = values < ev['iron_cut']
        return {'anemic_low': int(np.count_nonzero(anemia & low)),
                'anemic_high': int(np.count_nonzero(anemia & ~low)),
                'nonanemic_low': int(np.count_nonzero(~anemia & low)),
                'nonanemic_high': int(np.count_nonzero(~anemia & ~low))}

    cells = cells_for(y)
    for key, value in cells.items():
        if value != factor * int(ev[key]):
            raise AssertionError('Source joint cell mismatch: ' + key)
    if cells_for(reference_y) != cells:
        raise AssertionError('Reference pairing changed binary cells.')
    crude_or = (cells['anemic_low'] * cells['nonanemic_high']) / (cells['anemic_high'] * cells['nonanemic_low'])
    rx = pd.Series(x).rank(method='average').to_numpy()

    def spearman(values):
        ry = pd.Series(values).rank(method='average').to_numpy()
        return float(np.corrcoef(rx, ry)[0, 1])

    primary_rho = spearman(y)
    reference_rho = spearman(reference_y)
    minimum_rho = spearman(np.concatenate(reverse_ys))
    if not minimum_rho - 1e-12 <= reference_rho <= primary_rho + 1e-12:
        raise AssertionError('Reference correlation outside fixed-marginal extrema.')
    delta = primary_rho - reference_rho
    threshold = float(model['estimands']['comparison_with_initial']['material_absolute_change'])
    result = pd.DataFrame({'row_id': np.arange(len(x), dtype=np.int64),
                           'paired_index': np.concatenate(assignments).astype(np.int64)})
    if len(result) != factor * int(ev['n_total']):
        raise AssertionError('Total row count mismatch.')
    if result.columns.tolist() != ['row_id', 'paired_index']:
        raise AssertionError('Unexpected output columns.')
    if not all(pd.api.types.is_integer_dtype(t) for t in result.dtypes):
        raise AssertionError('Output must contain integers only.')
    result.attrs['estimands'] = {'crude_anemia_or': float(crude_or),
                                 'spearman_hb_ferritin': primary_rho,
                                 'cells_on_synthetic_rows': cells}
    result.attrs['comparison_with_initial'] = {
        'reference_spearman': reference_rho,
        'candidate_minus_reference': delta,
        'absolute_change': abs(delta),
        'material_absolute_change': threshold,
        'material_change_observed': bool(abs(delta) > threshold),
        'reference_method': 'Uniform within-band permutations using the supplied seed.'}
    result.attrs['fixed_marginal_sensitivity'] = {
        'minimum_spearman': minimum_rho,
        'maximum_spearman': primary_rho,
        'range': primary_rho - minimum_rho}
    result.attrs['marginal_diagnostics'] = {
        'groups': diagnostics,
        'overall_hb_gm': float(np.exp(np.mean(np.log(x)))),
        'overall_fe_gm': float(np.exp(np.mean(np.log(y))))}
    result.attrs['interpretation'] = 'Prespecified concordant-rank sensitivity scenario, not reconstructed source participants or an identified population correlation.'
    return result
